Chords $AB$ and $CD$ intersect inside the circle at $P$. $AP = 8\text{ cm}$, $PB = 3\text{ cm}$ and $CP = 6\text{ cm}$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}, scale=0.47]
\coordinate (O) at (0,0);
\coordinate (P) at (2.5,0.154);
\coordinate (A) at (-5.5,0.154);
\coordinate (B) at (5.5,0.154);
\coordinate (C) at (0.448,-5.484);
\coordinate (D) at (3.868,3.913);
\draw (O) circle (5.502);
\fill (O) circle (1.5pt);
\node[below] at (O) {$O$};
\draw (A) -- (B);
\draw (C) -- (D);
\fill (P) circle (1.5pt);
\node[below right] at (P) {$P$};
\node[left] at (A) {$A$};
\node[right] at (B) {$B$};
\node[below] at (C) {$C$};
\node[above] at (D) {$D$};
\end{tikzpicture}
[/tikz]
Find the length of $PD$.

